import React, { useState, useEffect } from "react";
import { Dialog, DialogActions, DialogContent, DialogTitle, Button, Box, TextField, Stack, Typography, LinearProgress } from "@mui/material";
import { styled } from "@mui/material/styles";

const StyledInput = styled(TextField)(({ theme }) => ({
  "& .MuiInputBase-input": {
  },
}));

const MediaDialog = ({ open, handleClose, handleSend, file, inputRef, value, setValue, setSelectedFile, uploading, progress }) => {

  const [previewUrl, setPreviewUrl] = useState(null);

  useEffect(() => {
    if (file) {
      const objectUrl = URL.createObjectURL(file);
      setPreviewUrl(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    }
    return () => {
      handleClose();
      setSelectedFile(null);
    }
  }, [file]);

  const handleKeyPress = (event) => {
    if (event.key === "Enter") {
      event.preventDefault(); // Prevents default Enter behavior
      handleSend(); // Call the function to send the message
    }
  };

  return (
    <>
      <Dialog open={open} onClose={handleClose} sx={{ p: 3 }}>
        <DialogTitle>Preview Media</DialogTitle>
        <DialogContent sx={{ pb: 1 }}>
          <Stack spacing={2}>
            <Box sx={{ width: "100%", display: "flex", justifyContent: "center", pt: 2.5 }}>
              {file && file.type.startsWith("image/") && (
                <img src={previewUrl} alt="Preview" style={{ maxWidth: "100%", maxHeight: "400px", borderRadius: 10 }} />
              )}
              {file && file.type.startsWith("video/") && (
                <video controls style={{ maxWidth: "100%", maxHeight: "400px" }}>
                  <source src={previewUrl} type={file.type} />
                  Your browser does not support the video tag.
                </video>
              )}
            </Box>
            {uploading && (
              <Box sx={{ width: '100%', mt: 2 }}>
                <Typography variant="body2">Uploading: {progress}%</Typography>
                <LinearProgress variant="determinate" value={progress} />
              </Box>
            )}
            <StyledInput
              placeholder="Write a message..."
              inputRef={inputRef}
              fullWidth
              multiline
              variant="outlined"
              value={value}
              onChange={(event) => setValue(event.target.value)}
              onKeyPress={handleKeyPress}
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose} color="secondary">Cancel</Button>
          <Button variant="contained" onClick={handleSend} disabled={uploading} color="primary">{uploading?"Uploading":"Send"}</Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default MediaDialog;
